import{z as i,x as s,o as t,c as p,q as A,j as n,D as e,d as r,s as o,S as l,b as E}from"./chunks/framework.C8m1ZpeB.js";const M=JSON.parse('{"title":"契约曲线与 MRS","description":"","frontmatter":{"title":"契约曲线与 MRS","date":"2026-09-08T00:00:00.000Z","section":"econ"},"headers":[],"relativePath":"econ/mrs-contract-curve.md","filePath":"econ/mrs-contract-curve.md","lastUpdated":1791063341000}'),m={name:"econ/mrs-contract-curve.md"};function d(h,a,D,u,C,c){const B=s("Mermaid");return t(),p("div",null,[a[2]||(a[2]=A('<h1 id="契约曲线与-mrs" tabindex="-1">契约曲线与 MRS <a class="header-anchor" href="#契约曲线与-mrs" aria-label="Permalink to &quot;契约曲线与 MRS&quot;">​</a></h1><div class="epigraph"><p>盒中无差异曲线相切的轨迹，就是契约曲线；切点上两人的边际替代率相等，那是内点有效的几何，还不是价格。</p><footer>—— 据 Varian, Intermediate Microeconomics；Mas-Colell, Whinston and Green 第 15–16 章整理</footer></div><p>定位：<a href="/econ/edgeworth-pareto">上一课</a>。埃奇沃思盒已经把可行配置画成矩形，并把帕累托集叫做合同曲线，也写下了内点 \\(\\mathrm{MRS}^A=\\mathrm{MRS}^B\\)。本课不从「什么是交易」起笔，也不重讲透镜与公平。缺口是几何与可微刻画怎样一一对应：切点、角点、支撑价格的斜率，以及契约曲线为什么通常是一条曲线而不是一个点。</p><h2 id="问题" tabindex="-1">问题 <a class="header-anchor" href="#问题" aria-label="Permalink to &quot;问题&quot;">​</a></h2><p>上一课用「不存在帕累托改进」定义有效。可微、严格凸、内点时，这句话等价于无差异曲线相切，即</p> \\[\\mathrm{MRS}_{12}^A(x^A)=\\mathrm{MRS}_{12}^B(x^B)=\\frac{\\partial u^A/\\partial x_1^A}{\\partial u^A/\\partial x_2^A}. \\]<p>缺口是把等价说清楚，并标出它<strong>还不是</strong>瓦尔拉斯均衡：相切只对齐两人的边际评价，没有要求这条公切线通过禀赋点，也没有要求两人在同一预算上最优。公切线的斜率将是后课的价格比；本课只把斜率从几何里读出来。</p><p>契约曲线是满足切条件（及可行性）的点的轨迹。给定偏好，它在盒里通常从一边伸到另一边；给定禀赋，互利交易只落在透镜与轨迹的交集。集合大，正是需要拍卖人的原因。</p><p><span class="marginnote">数字实例：若 \\(A\\) 的 MRS 为 3（愿拿 3 个苹果换 1 个橘子），\\(B\\) 的 MRS 为 1（1 换 1 就行），那么任何介于 1 与 3 之间的交换比率都让两人同时变好——比如 2 换 1。两人 MRS 的差距就是交易的「利润空间」，差距归零，交易停。</span></p><h3 id="相切是内点条件-不是有效的定义" tabindex="-1">相切是内点条件，不是有效的定义 <a class="header-anchor" href="#相切是内点条件-不是有效的定义" aria-label="Permalink to &quot;相切是内点条件，不是有效的定义&quot;">​</a></h3><p>定义始终是「没有可行的改进」。非凸时相切可以不是局部最优；角点时不相切也可以有效。把 MRS 相等当成定义，会在轴上和凹偏好处说错话。上一课已埋伏角点；本课用图把轴上的不等式画出来。</p><p><span class="marginnote">MRS 是商品 2 计的商品 1 的边际评价。盒里 \\(A\\) 的无差异从左下、 \\(B\\) 从右上。相切意味着过该点能画出一条同时支撑两条无差异曲线的直线——后课把它叫做预算。</span></p><p><span class="marginnote">常见误区：把「相切」当成有效的定义。它只是内点、可微、凸偏好下的等价刻画；角点上有效配置可以不相切，非凸时相切甚至可能不是最优。定义始终是「不存在可行的改进」。</span></p><h2 id="方法" tabindex="-1">方法 <a class="header-anchor" href="#方法" aria-label="Permalink to &quot;方法&quot;">​</a></h2><p>对内点有效配置，用拉格朗日（可行性 \\(x^A+x^B=\\omega\\)）或直接从「改进方向」推切条件：若 \\(\\mathrm{MRS}^A\\gt \\mathrm{MRS}^B\\)，\\(A\\) 愿用比 \\(B\\) 所要的更少的商品 2 换一单位商品 1，交换改进双方。严格凸保证切点是切不是交。把 \\(x^A\\) 沿可行性消去，切条件给出 \\(x_1^A\\) 与 \\(x_2^A\\) 的关系，即契约曲线方程。</p><p>准线性、柯布–道格拉斯等教具上曲线可写成显式；本课不把显式当一般定理。提供曲线（offer curve）是价格变动时需求的轨迹，与契约曲线相交于均衡——那是下一课，本课禁止提前解 \\(z(p)=0\\)。</p>',16)),(t(),n(l,null,{default:e(()=>[o(B,{id:"mermaid-44",class:"mermaid",graph:"flowchart%20TD%0A%20%20BOX%5B%22%E5%9F%83%E5%A5%87%E6%B2%83%E6%80%9D%E7%9B%92%EF%BC%9A%E5%8F%AF%E8%A1%8C%22%5D%20--%3E%20PE%5B%22%E5%B8%95%E7%B4%AF%E6%89%98%EF%BC%9A%E6%97%A0%E6%94%B9%E8%BF%9B%22%5D%0A%20%20PE%20--%3E%20INT%5B%22%E5%86%85%E7%82%B9%20%2B%20%E5%8F%AF%E5%BE%AE%EF%BC%9AMRS%20%E7%9B%B8%E7%AD%89%22%5D%0A%20%20INT%20--%3E%20CC%5B%22%E5%A5%91%E7%BA%A6%E6%9B%B2%E7%BA%BF%EF%BC%9A%E5%88%87%E7%82%B9%E8%BD%A8%E8%BF%B9%22%5D%0A%20%20CC%20--%3E%20PRICE%5B%22%E5%85%AC%E5%88%87%E7%BA%BF%E6%96%9C%E7%8E%87%20%3D%20%E5%90%8E%E8%AF%BE%E7%9A%84%E4%BB%B7%E6%A0%BC%E6%AF%94%22%5D%0A%20%20PE%20--%3E%20COR%5B%22%E8%A7%92%E7%82%B9%EF%BC%9AMRS%20%E4%B8%8D%E7%AD%89%E5%BC%8F%22%5D%0A"})]),fallback:e(()=>[...a[0]||(a[0]=[r(" Loading... ",-1)])]),_:1})),a[3]||(a[3]=E("p",null,"有生产时，总量沿 PPF 变，有效还要求 \\(\\mathrm{MRS}=\\mathrm{MRT}\\)。本课边长仍固定，只补交换几何；生产一般均衡后课再接。",-1)),a[4]||(a[4]=E("h2",{id:"机制",tabindex:"-1"},[r("机制 "),E("a",{class:"header-anchor",href:"#机制","aria-label":'Permalink to "机制"'},"​")],-1)),a[5]||(a[5]=E("p",null,"为什么轨迹一般是一维：两种商品、两人、可行性吃掉两个变量，切条件再吃一个，剩下一个自由度——这就是「曲线」。\\(I\\) 人 \\(L\\) 商品时，帕累托集是 \\(L(I-1)\\) 维里的 \\(L-1\\) 个切条件之后的流形，矩形画不出，定义不改。",-1)),a[6]||(a[6]=E("p",null,[r("公切线已经几乎是价格：它给一个共同的交换比率。缺的是：这个比率要让两人"),E("strong",null,"愿意"),r("停在切点，而不是沿着切线滑到别处。那需要预算通过各自的禀赋（或转移后的财富），即瓦尔拉斯。本课只保证「有效 \\(\\Rightarrow\\) 存在一条支撑两条无差异的直线」在凸、内点时成立。")],-1)),a[7]||(a[7]=E("p",null,"从禀赋出发的交易路径不必沿契约曲线走。透镜里的点都可以是某次双边议价的停靠；只有到达曲线上，改进才消失。Edgeworth 的 recontracting 想象联盟不断重订合同，极限落在核里，两人时核就是透镜与曲线的交。本课几何停在曲线本身；核是后课用联盟阻塞再瘦一次。",-1)),a[8]||(a[8]=E("p",null,[E("span",{class:"marginnote"},"直觉类比：契约曲线像一条「谈判走廊」——走廊里每一点都无人能拒绝再改（有效），但停在哪一点取决于谈判力与出发禀赋；价格体系只是后课用来在走廊里挑出一个点的拍卖人。")],-1)),(t(),n(l,null,{default:e(()=>[o(B,{id:"mermaid-63",class:"mermaid",graph:"flowchart%20TD%0A%20%20GAP%5B%22MRS_A%20%E5%A4%A7%E4%BA%8E%20MRS_B%22%5D%20--%3E%20T%5B%22A%20%E8%A7%86%E5%95%86%E5%93%81%201%20%E6%9B%B4%E7%8F%8D%E8%B4%B5%22%5D%0A%20%20T%20--%3E%20TRADE%5B%22A%20%E7%94%A8%E5%95%86%E5%93%81%202%20%E6%8D%A2%E5%95%86%E5%93%81%201%EF%BC%8C%E5%8F%8C%E6%96%B9%E6%94%B9%E5%96%84%22%5D%0A%20%20TRADE%20--%3E%20MOVE%5B%22%E9%85%8D%E7%BD%AE%E6%9C%9D%20MRS%20%E5%B7%AE%E8%B7%9D%E7%BC%A9%E5%B0%8F%E7%9A%84%E6%96%B9%E5%90%91%E7%A7%BB%E5%8A%A8%22%5D%0A%20%20MOVE%20--%3E%20EQ%7B%22MRS_A%20%E4%B8%8E%20MRS_B%20%E7%9B%B8%E7%AD%89%EF%BC%9F%22%7D%0A%20%20EQ%20--%20%22%E5%90%A6%EF%BC%8C%E7%BB%A7%E7%BB%AD%E6%8D%A2%22%20--%3E%20TRADE%0A%20%20EQ%20--%20%22%E6%98%AF%22%20--%3E%20STOP%5B%22%E5%88%B0%E8%BE%BE%E5%A5%91%E7%BA%A6%E6%9B%B2%E7%BA%BF%EF%BC%9A%E6%97%A0%E5%86%8D%E6%94%B9%E8%BF%9B%22%5D%0A%20%20STOP%20--%3E%20OPEN%5B%22%E6%96%9C%E7%8E%87%E5%B0%9A%E6%9C%AA%E8%A2%AB%E6%8C%91%E4%B8%AD%EF%BC%9A%E5%9D%87%E8%A1%A1%E8%BF%98%E5%B7%AE%E9%A2%84%E7%AE%97%E6%9D%A1%E4%BB%B6%22%5D%0A"})]),fallback:e(()=>[...a[1]||(a[1]=[r(" Loading... ",-1)])]),_:1})),a[9]||(a[9]=A('<p><span class="marginnote">不要把契约曲线上的点写成限价簿的成交价。曲线上没有队列、没有价差；每一点是配置，斜率还没有被市场挑中。</span></p><h2 id="边界" tabindex="-1">边界 <a class="header-anchor" href="#边界" aria-label="Permalink to &quot;边界&quot;">​</a></h2><p>不可分商品让切条件失效，核与匹配用另一套语言。外部性使「盒的边长」不能概括他人的效应，帕累托条件要改。后课<a href="/econ/walrasian-equilibrium">瓦尔拉斯均衡</a>用价格在契约曲线上挑点；本课不挑。</p><p>后课默认：说到内点有效，即盒里 MRS 对齐、配置在契约曲线上；均衡还要预算与出清。</p><h2 id="小结" tabindex="-1">小结 <a class="header-anchor" href="#小结" aria-label="Permalink to &quot;小结&quot;">​</a></h2><ul><li>内点有效 \\(\\Leftrightarrow\\) 无差异相切 \\(\\Leftrightarrow\\) MRS 相等；定义仍是无改进。</li><li>契约曲线是切点轨迹，一般不是单点；透镜只截一段。</li><li>公切线的斜率预示价格比，但本课还没有拍卖人。</li><li>下一课用价格当公共信号，在曲线上挑出清的一点。</li><li>出处：Varian, <em>Intermediate Microeconomics</em>；Mas-Colell, Whinston and Green 第 15–16 章；Edgeworth, 1881。</li></ul>',6))])}const R=i(m,[["render",d]]);export{M as __pageData,R as default};
